const items = $input.all();
const seen = new Set();
const result = [];

for (const item of items) {
  const userId  = item.json['User ID'];
  const account = item.json['Аккаунт'];

  if (!userId || String(userId).trim() === '') continue;
  if (!account || String(account).trim() === '') continue;

  if (seen.has(account)) continue;
  seen.add(account);

  result.push(item);
}

console.log(`К отправке: ${result.length} (аккаунтов: ${seen.size})`);
return result;

